def migrate_legacy_site_identity(apps, schema_editor):
    """Move the former settings.py site identity into the active profile.

    Existing admin customisations win; only Redefine's untouched placeholder
    values are replaced.
    """
    SiteConfiguration = apps.get_model("blog", "SiteConfiguration")
    site = SiteConfiguration.objects.filter(is_active=True).first()
    if site is None:
        site = SiteConfiguration.objects.first()
    if site is None:
        return

    if site.site_name in {"Theme Redefine", "My Site"}:
        site.site_name = "Theme Redefine"
    if site.site_subname == "Redefine Your Hexo Journey.":
        site.site_subname = ""
    if site.site_author == "The Redefine Team":
        site.site_author = "Site Author"
    site.site_description = "A Django blog based on Theme Redefine"
    site.site_keywords = "Django, Redefine, Blog"
    site.save(
        update_fields=(
            "site_name",
            "site_subname",
            "site_author",
            "site_description",
            "site_keywords",
        )
    )


